'use strict';
const sourceReplica='https://github.com/fanhao375/microduck-replica/tree/b5381d86b68d2e4f4606170d54d1f3f46d249ffc';
const badge=(text,kind='draft')=>`<span class="badge ${kind}">${text}</span>`;
const photo=(name,alt,extra='')=>`<img src="assets/${name}.jpg" alt="${alt}" ${extra}>`;
const photoCredit='参考素材 · microduck-replica contributors · CC BY-NC-SA 4.0';
const sampleData=Array.from({length:101},(_,i)=>({t:i/10,goal:i<15?120:i<65?128:120,actual:120+(i<15?0:i<65?8*(1-Math.exp(-(i-15)/6)):8*Math.exp(-(i-65)/7))+.3*Math.sin(i/3)}));
function chart(dark=false,height=230,accessible='示例关节位置曲线，目标与实际均为生成数据'){const w=window.innerWidth<=760?340:660,h=window.innerWidth<=760?Math.min(height,210):height,l=40,r=16,t=15,b=32;const X=i=>l+i/100*(w-l-r),Y=v=>h-b-(v-118)/12*(h-t-b);const line=key=>sampleData.map((d,i)=>(i?'L':'M')+X(i).toFixed(1)+','+Y(d[key]).toFixed(1)).join(' ');let grid='';[118,122,126,130].forEach(v=>{grid+=`<line x1="${l}" x2="${w-r}" y1="${Y(v)}" y2="${Y(v)}" stroke="${dark?'#495342':'#daddd3'}"/><text x="${l-10}" y="${Y(v)+4}" text-anchor="end">${v}</text>`});[0,2,4,6,8,10].forEach(v=>{grid+=`<text x="${X(v*10)}" y="${h-8}" text-anchor="middle">${v}s</text>`});return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${accessible}">${grid}<path d="${line('goal')}" fill="none" stroke="#f2b544" stroke-width="3" stroke-dasharray="7 5"/><path d="${line('actual')}" fill="none" stroke="${dark?'#aec594':'#466448'}" stroke-width="3"/><text x="${l}" y="10">ticks</text></svg>`}
const legend='<div class="chart-legend"><span><i class="legend-dot"></i>目标位置</span><span><i class="legend-dot actual"></i>实际位置</span></div>';
const callout=(title,body,kind='')=>`<aside class="callout ${kind}"><strong>${title}</strong><p>${body}</p></aside>`;
const codeBlock=(label,code)=>`<div class="code-block"><div class="code-header"><span>${label}</span><button data-copy>复制</button></div><pre><code>${code}</code></pre></div>`;
const home=()=>`<div class="wrap"><section class="home-hero"><div><span class="eyebrow"><i class="rule"></i>OPEN HARDWARE · EXPERIMENT NOTES</span><h1>把机器鸭，<br>从零<em>做出来。</em></h1><p class="hero-description">Microduck 的复刻、连接与调试笔记。<br>从第一颗螺丝，到一次可信的状态回读。</p><div class="button-row"><a class="button primary" href="#learn">从教程开始</a><a class="button secondary" href="#showcase">查看实验展示</a></div><div class="hero-meta"><div><strong>Radxa Zero 3W</strong>开发板基线</div><div><strong>15 个舵机</strong>源码默认 ID 组</div><div><strong>二维记录</strong>目标 · 实际 · 事件</div></div></div><figure class="hero-photo" style="margin:0">${photo('product','复刻仓库中红黄白色 Microduck 的正面实物参考照片')}<span class="photo-label">${badge('来源照片','draft')}</span><div class="photo-note">先把它装好。<br>再让每个动作有据可查。</div><figcaption class="photo-caption"><span>${photoCredit}</span><span>01 / 实物参考</span></figcaption></figure></section><div class="principles"><div><span class="number">01</span><h3>复用已经跑通的工具</h3><p>沿用 servo-web 与 feetech 总线实现，让新界面围绕真实接口工作。</p></div><div><span class="number">02</span><h3>先看状态，再做动作</h3><p>设备身份、校准状态和操作回执，是调试的第一步。</p></div><div><span class="number">03</span><h3>把过程变成可复现记录</h3><p>条件、变化、二维数据与事件一起保存，留给下一次实验。</p></div></div></div><section class="section"><div class="wrap split build-story"><figure class="story-image" style="margin:0">${photo('assembly','复刻仓库的手持装配参考照片','loading="lazy"')}<figcaption class="photo-caption">${photoCredit}</figcaption></figure><div class="story-copy"><span class="eyebrow">THE BUILD JOURNEY</span><h2>不只记录成品。<br>也记录它怎样被做出来。</h2><p class="muted">教程沿着硬件、系统、连接、校准和调试的顺序展开。每个结论保留来源，团队验证后再补上实测条件。</p><div class="step-list"><div class="step"><span class="number">01</span><div><strong>准备与装配</strong><p>物料、机械版本、布线和上电检查。</p></div></div><div class="step"><span class="number">02</span><div><strong>系统与连接</strong><p>Wi-Fi、USB 网络与 BLE 桥接，各有适用条件。</p></div></div><div class="step"><span class="number">03</span><div><strong>校准与调试</strong><p>识别关节，观察回读，再进行小幅台架测试。</p></div></div></div><a class="button ghost" href="#learn">阅读完整路线</a></div></div></section><section class="section dark"><div class="wrap record-teaser"><div><span class="eyebrow">LESS GUESSING. MORE EVIDENCE.</span><h2>动作之外，<br>留下它的证据。</h2><p class="muted">目标位置、实际回读和事件沿同一条时间线展开。展示结果，也保留条件和待解决的问题。</p><div class="button-row"><a class="button primary" href="#records">打开示例记录</a></div></div><div class="chart-card"><div class="chart-title"><span>左膝 · 位置回读</span>${badge('示例数据','example')}</div>${chart(true)}${legend}<p class="small muted" style="margin:18px 0 0">曲线由示例数据生成，未连接真实设备。</p></div></div></section><div class="wrap start-strip"><div><span class="eyebrow">YOUR FIRST SESSION</span><h2>先连上，再看清。</h2></div><a class="button secondary" href="#article">阅读连接教程</a></div>`;
const experiments=[{title:'关节回读与小幅动作',sub:'BENCH / 01',description:'视频与日志待补 · 布局示例'},{title:'掉线后的状态与恢复',sub:'CONNECTION / 02',description:'实测待补 · 验收场景'}];
let experimentIndex=0;
const showcase=()=>`<div class="wrap"><section class="page-intro showcase-head"><div><span class="eyebrow">EXPERIMENTS / IN THE REAL WORLD</span><h1>让结果自己说话。</h1></div><p>实机视频是主体，数据与实验条件提供上下文。没有日志时，视频独立展示。</p></section><section class="showcase-player"><div class="video-surface">${photo('product','实机视频封面布局的参考照片')}<div class="video-top">${badge('视频待补','draft')}${badge('参考封面','draft')}</div><div class="video-overlay"><span class="video-placeholder" aria-hidden="true">▷</span><h3>${experiments[experimentIndex].title}</h3><p>收到团队实机视频后替换此区域。<br>当前没有可播放视频，不代表已完成动作。</p></div><div class="video-bottom"><span>MICRODUCK LAB · EXPERIMENT ${String(experimentIndex+1).padStart(2,'0')}</span><span>视频 — / 日志 —</span></div></div><aside class="experiment-rail"><span class="eyebrow">SELECT AN EXPERIMENT</span>${experiments.map((e,i)=>`<button class="experiment-switch ${i===experimentIndex?'active':''}" data-experiment="${i}" aria-pressed="${i===experimentIndex}"><span>${e.sub}</span><strong>${e.title}</strong><p>${e.description}</p></button>`).join('')}<p class="small muted" style="margin:18px 0 0">这里保留实际实验入口，团队素材到位后再公开结果。</p></aside></section><div class="evidence-line"><div>${badge('实测待补')}<span>硬件 / 版本 / 视频 / 日志均需关联记录</span></div><a href="#article">查看连接前的检查</a></div><div class="playback-row"><div><div class="chart-title"><h3>与动作对应的二维记录</h3>${badge('示例曲线','example')}</div>${chart(false,220)}${legend}<p class="small muted" style="margin-top:18px">示例曲线仅展示数据版式。视频与日志没有真实时间对应关系时，不显示同步播放。</p></div><aside><h3>这次实验的条件</h3><ul class="fact-list"><li><span>台架与支撑</span><span>待记录</span></li><li><span>开发板 / 系统镜像</span><span>待记录</span></li><li><span>控制服务 / 机械版本</span><span>待记录</span></li><li><span>校准与动作范围</span><span>待核实</span></li><li><span>数据采集与时钟</span><span>待核实</span></li></ul><a class="button ghost" href="#records">查看记录版式</a></aside></div></div><section class="section"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">FROM SYMPTOM TO EVIDENCE</span><h2>实验案例</h2></div><p>不只保留“成功了”。也保留问题怎样被发现、调整和验证。</p></div><div class="case-grid"><article class="case-item">${badge('案例模板')}<h3>目标位置与实际回读的差异</h3><p>先记录测试条件，再核对单位、校准与回读。将两次实验放在相同时间轴上比较。</p><div class="comparison"><div><span>调整之前</span><strong>测量待补</strong></div><div><span>调整之后</span><strong>测量待补</strong></div></div><a href="#case" class="button secondary">查看案例结构</a></article><article class="case-item">${badge('案例模板')}<h3>连接中断后，界面如何恢复</h3><p>保留最后更新时间与断线事件。重连后重新取得身份和状态，旧动作不会自动重发。</p><div class="comparison"><div><span>现场条件</span><strong>测试待执行</strong></div><div><span>验证结果</span><strong>结果待补</strong></div></div><a href="#console" class="button secondary">查看状态设计</a></article></div></div></section>`;
const lessons=[['准备一套可复现的硬件','确认板卡、机械件和舵机版本，整理物料与供电条件。','物料 / 版本 / 上电检查'],['装配与布线','沿机械结构逐步装配，保留方向、线序和检查照片。','机械 / 电源 / 总线'],['板端系统与服务','记录镜像、内核与服务版本，明确运行模式和总线归属。','Radxa / Linux / servo-web'],['连接到开发板','按电脑系统选择 Wi-Fi、USB 网络或 BLE 桥接路径。','Windows / Linux / macOS'],['校准与第一次回读','核对设备身份、在线舵机、位置单位和安全动作范围。','ID / 方向 / 零位 / 回执'],['测试、导出与团队案例','保存数据、事件与实验条件，让下一次测量可比较。','二维曲线 / 日志 / 复现']];
let selectedOS='Windows';
const articleSections=[{id:'preflight',label:'开始之前'},{id:'route',label:'选择连接路径'},{id:'network',label:'打开板端页面'},{id:'identity',label:'核对服务与身份'},{id:'diagnose',label:'连接不通时'},{id:'sources',label:'来源与适用边界'}];
const outlineSections=[{id:'chapter-evidence',label:'本章证据'},{id:'chapter-conditions',label:'适用环境'},{id:'chapter-steps',label:'操作与检查'},{id:'chapter-results',label:'现场结果'}];
const chapterHref=i=>i===3?'#article':'#article/chapter-'+i;
function tutorialNavigation(current,sections){return `<aside class="article-toc" aria-label="教程章节与本章目录"><a href="#learn" class="toc-index">教程目录</a><h4>章节导航</h4><nav class="tutorial-chapters" aria-label="教程章节">${lessons.map((lesson,i)=>`<div class="chapter-nav-item"><a class="chapter-link ${i===current?'is-current':''}" href="${chapterHref(i)}" ${i===current?'aria-current="page"':''}><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><span>${lesson[0]}</span></a>${i===current?`<nav class="toc-sections" aria-label="本章内容">${sections.map((s,n)=>`<a class="toc-section-link ${n===0?'active':''}" data-section="${s.id}" href="${chapterHref(i)}/${s.id}" ${n===0?'aria-current="location"':''}>${s.label}</a>`).join('')}</nav>`:''}</div>`).join('')}</nav></aside>`}
const learn=()=>`<div class="wrap"><section class="page-intro"><div class="learn-top"><div><span class="eyebrow">FIELD GUIDE / BUILD · CONNECT · MEASURE</span><h1>一颗螺丝，<br>一条清楚的路线。</h1><p>从准备到调试，把复刻过程写成可跟随的教程。每一章保留适用版本、来源和待验证项。</p><div class="button-row"><a href="#article" class="button primary">阅读连接章节</a><a href="#case" class="button secondary">查看案例结构</a></div></div><figure class="learn-photo" style="margin:0">${photo('assembly','装配与布线章节的实物参考照片')}<span class="photo-label">${badge('来源照片')}</span><figcaption class="photo-caption">${photoCredit}</figcaption></figure></div><div class="learn-intro-line"><span>6 个章节</span><span>Radxa Zero 3W</span><span>三种电脑系统</span><span>文稿待团队验证</span></div></section><section class="section learn-curriculum"><aside class="learn-aside"><span class="eyebrow">CHOOSE YOUR PATH</span><h3>按自己的环境阅读</h3><p>选择电脑系统只调整阅读提示。兼容性仍以对应硬件测试为准。</p><div class="os-select" aria-label="电脑系统">${['Windows','Linux','macOS'].map(os=>`<button data-os="${os}" class="${os===selectedOS?'active':''}" aria-pressed="${os===selectedOS}">${os}</button>`).join('')}</div><p class="small" style="margin-top:22px" id="os-note">${osNote()}</p><hr class="divider"><p style="margin-top:24px">缺少自己的镜像与机械版本时，先补充环境记录，再执行校准和动作。</p></aside><div>${lessons.map((l,i)=>`<article class="lesson"><span class="lesson-no">${String(i+1).padStart(2,'0')}</span><div><h3>${l[0]}</h3><p>${l[1]}</p><div class="lesson-meta"><span>${l[2]}</span>${badge(i===3?'草稿已整理':'内容待补')}</div></div><a class="button ghost" href="${i===3?'#article':'#article/chapter-'+i}">${i===3?'阅读草稿':'查看提纲'}</a></article>`).join('')}</div></section></div><section class="section dark"><div class="wrap split"><div><span class="eyebrow">WRITE THE NEXT CHAPTER</span><h2>把遇到的问题，<br>写成下一位同伴的线索。</h2></div><div><p class="muted">团队案例从问题现象开始，留下环境、证据、调整和验证结果。没有测量支持的判断，保留为待验证。</p><a href="#case" class="button primary">查看案例结构</a></div></div></section>`;
function osNote(){return selectedOS==='Windows'?'USB 网络优先核实 Windows 版本、NCM 支持与板端枚举结果。':selectedOS==='macOS'?'记录 Intel / Apple Silicon、系统版本和 USB / BLE 路径实测。':'记录发行版、内核、USB 枚举与 BlueZ / 权限条件。'}
const article=()=>`<div class="wrap"><section class="article-top"><div class="breadcrumb"><a href="#learn">教程</a><span>/</span><span>04 连接到开发板</span><span>/</span><span>Wi-Fi</span></div><header class="article-header"><span class="eyebrow">04 / CONNECT TO THE BOARD</span>${badge('教程草稿')}<h1>先通过 Wi-Fi，<br>建立一次清楚的连接。</h1><p>把电脑与 Radxa 放到可互通的网络，打开板端提供的同源网页。先读取服务信息，再进入设备调试。</p><div class="article-meta"><span>适用基线 · Radxa Zero 3W</span><span>源码 · servo-web 0.15.4</span><span>更新 · 2026.10.04</span><span>团队实测 · 待执行</span></div></header></section><div class="article-layout">${tutorialNavigation(3,articleSections)}<article class="article-body"><h2 id="preflight">01 开始之前</h2><p>先确认板卡能正常供电、系统已经启动，电脑与板卡在允许互通的网络内。记录当前镜像和内核版本；在真实设备上核对服务的运行方式与串口归属。</p>${callout('先确认总线的唯一写入者','校准台后端与机器人运行时应互斥访问同一总线。进入调试前，必须确认当前模式和实际运行的服务。','attention')}<ol><li>记录板卡与机械版本，确认供电和数据线布置。</li><li>确认电脑与板卡的网络地址，以及网络是否允许互访。</li><li>从现有项目取得服务入口。没有核对镜像前，不套用未知的安装或启动命令。</li></ol><figure class="article-figure">${photo('assembly','布线与装配的参考照片','loading="lazy"')}<figcaption>${photoCredit}<br>此图不是团队接线验收图。具体供电与线序需按自己的机械版本核对。</figcaption></figure><h2 id="route">02 选择连接路径</h2><table><thead><tr><th>连接方式</th><th>网页入口与检查重点</th></tr></thead><tbody><tr><td>Wi-Fi</td><td>打开板端网页。确认网络互通、实际 IP 与服务端口。</td></tr><tr><td>USB-C</td><td>USB-C 1 / OTG 配置虚拟网卡后，复用同一网页与 API。UDC、描述符、地址与三系统枚举待实测。</td></tr><tr><td>蓝牙 BLE</td><td>优先复用官方 duckctl / btd，通过电脑本地桥接提供网页入口。开放能力依据真实服务与带宽。</td></tr></tbody></table><p>Wi-Fi 与 USB 网络使用同一套板端接口。USB-C 2 是 HOST；插入 USB-C 数据线不等于自动出现网络或串口设备。</p><h2 id="network">03 打开板端页面</h2><p>当前冻结的 servo-web 源码默认绑定 <span class="mono">0.0.0.0:8080</span>。端口可能被启动参数改变，使用板端实际配置。下方地址是占位符，不代表已发现设备。</p>${codeBlock('浏览器地址 · 替换 &lt;板端 IP&gt;', 'http://&lt;板端 IP&gt;:8080/\n\n# 只读服务信息\nhttp://&lt;板端 IP&gt;:8080/api/info')}<p>设备控制进入板端或本地桥接提供的网页。公开展示网站保留介绍、教程与记录阅读入口。</p><h2 id="identity">04 核对服务与身份</h2><p>首次连接先读取服务信息。现有 <span class="mono">/api/info</span> 会返回版本、舵机 ID、在线状态和日志等字段。项目所需的唯一设备身份、单写入租约与完整操作回执仍需在适配层补齐。</p>${codeBlock('字段结构示意 · 不是设备返回结果','{\n  "version": "0.15.4",\n  "ids": [ /* 配置的舵机 ID */ ],\n  "present": [ /* 在线舵机 ID */ ],\n  "names": { /* 关节名称 */ },\n  "fake": false\n}')}<p>真实 <span class="mono">fake</span> 字段用于区分后端测试模式；本视觉原型没有请求 API。没有校准映射时，位置以源码的 ticks 呈现，不虚构角度单位。</p>${callout('进入调试台只打开面板','教程入口不自动使能舵机，也不执行动作。先看身份、校准与回读，再决定下一步。')}<h2 id="diagnose">05 连接不通时</h2><table><thead><tr><th>现象</th><th>先核对</th></tr></thead><tbody><tr><td>页面打不开</td><td>地址、实际端口、网络隔离和服务运行状态。</td></tr><tr><td>有网页，没有回读</td><td>WebSocket /ws、总线归属、串口配置与在线舵机。</td></tr><tr><td>数据长时间不更新</td><td>最后更新时间与断线事件。重新确认连接，不自动重发旧动作。</td></tr></tbody></table><h2 id="sources">来源与适用边界</h2><p>本章依据冻结源码整理。实际镜像、板卡版本、Windows / Linux / macOS 兼容性与真实动作验收仍待团队验证。</p><ul class="source-list"><li><a href="${sourceReplica}/tools/servo-web" target="_blank" rel="noreferrer">microduck-replica / tools/servo-web · b5381d8</a></li><li><a href="https://github.com/pollen-robotics/microduck/blob/9136aa4ee88e81edf2bcaf3527e90b65da25f1eb/docs/robot/duckctl.md" target="_blank" rel="noreferrer">官方 duckctl 文档 · 9136aa4</a></li><li><a href="https://docs.radxa.com/en/zero/zero3/hardware-design/hardware-interface" target="_blank" rel="noreferrer">Radxa Zero 3W 接口说明</a></li></ul><div class="article-next"><div><p>下一步 / 核对设备状态</p><h3>先看见真实回读。</h3></div><a class="button primary" href="#console">打开调试台原型</a></div></article></div></div>`;
const chapterOutline=i=>`<div class="wrap"><section class="article-top"><div class="breadcrumb"><a href="#learn">教程</a><span>/</span><span>${String(i+1).padStart(2,'0')} ${lessons[i]?.[0]||'章节'}</span></div><header class="article-header">${badge('章节提纲 · 正文待补')}<h1>${lessons[i]?.[0]||'章节提纲'}</h1><p>${lessons[i]?.[1]||''}</p></header></section><div class="article-layout">${tutorialNavigation(i,outlineSections)}<article class="article-body"><span class="eyebrow">CHAPTER OUTLINE</span><h2 id="chapter-evidence">本章需要留下的证据</h2><div class="step-list"><div class="step" id="chapter-conditions"><span class="number">01</span><div><strong>适用环境</strong><p>机械、系统、软件与硬件版本。</p></div></div><div class="step" id="chapter-steps"><span class="number">02</span><div><strong>操作与检查</strong><p>${lessons[i]?.[2]||''}，以及预期现象。</p></div></div><div class="step" id="chapter-results"><span class="number">03</span><div><strong>现场结果</strong><p>团队照片、真实日志与复现记录。</p></div></div></div>${callout('素材与实测待补','该页面展示教程提纲和阅读版式。尚未编写或验证本章完整操作步骤。')}<a href="#article" class="button primary">阅读已整理的连接草稿</a></article></div></div>`;
// 完整默认配置：缺少回读只影响数值，不删除关节。
let jointID=23, consoleState='example';
let recordIndex=0;
const records=()=>`<div class="wrap"><section class="page-intro"><span class="eyebrow">RECORDS / KEEP THE CONTEXT</span><div class="section-heading"><div><h1>留下这一次。</h1><p>把位置、事件和条件保存在一起，下次调试从证据开始。</p></div><button class="button secondary" disabled title="真实记录导入在后续开发阶段完成">导入实测记录 · 待开发</button></div></section><section class="records-layout" style="padding-bottom:72px"><aside class="record-index"><button class="record-entry ${recordIndex===0?'active':''}" data-record="0" aria-pressed="${recordIndex===0}">${badge('示例记录','example')}<h3>左膝位置回读</h3><p>10 秒 · 位置 / 目标 / 事件<br>生成数据 · 未连接设备</p></button><button class="record-entry ${recordIndex===1?'active':''}" data-record="1" aria-pressed="${recordIndex===1}">${badge('实测待补')}<h3>你的第一次测量</h3><p>等待真实导出记录<br>设备与版本条件待填写</p></button></aside><article class="record-detail">${recordIndex===0?`<h2>左膝位置回读</h2><div class="detail-metadata"><span class="mono">EXAMPLE-01</span><span>关节 #23 · left_knee</span><span>时长 10.0 s</span><span>时间基准 · 示例相对时钟</span></div><div class="record-chart"><div class="chart-controls"><span>关节位置 · ticks</span>${badge('生成数据','example')}</div>${chart(false,270)}${legend}<div class="timeline"><output id="playback-time">0.0 s</output><input type="range" min="0" max="10" value="0" step=".1" aria-label="示例记录时间" id="playback-range"><span>10.0 s</span></div><p class="small muted" style="margin:14px 0 0">游标展示样例时间点，未关联实机视频。曲线包含完整 10 秒。</p></div><div class="record-metrics"><div><strong>101</strong><span>生成的样例点</span></div><div><strong>3</strong><span>样例事件</span></div><div><strong>—</strong><span>实机验证结果</span></div></div><div class="section-heading" style="margin-bottom:14px"><h3>事件</h3><button class="button ghost" data-export>下载示例 CSV</button></div><table class="event-table"><thead><tr><th>时间</th><th>事件内容</th><th>来源</th></tr></thead><tbody><tr><td>0.0 s</td><td>样例记录开始</td><td>原型生成</td></tr><tr><td>1.5 s</td><td>目标位置切换至 128 ticks</td><td>原型生成</td></tr><tr><td>6.5 s</td><td>目标位置切换至 120 ticks</td><td>原型生成</td></tr></tbody></table>${callout('这不是硬件测量','CSV 明确包含 sample=true 与示例来源。真实记录导入、回放、比较与往返验证留在开发阶段。')}`:`<h2>第一次实测记录</h2><div class="empty-state"><h3>等待真实设备记录</h3><p>导入时保留设备身份、软件与硬件版本、单位、时间基准和实验条件。</p></div><ul class="fact-list"><li><span>设备与唯一标识</span><span>待取得</span></li><li><span>服务 / 镜像 / 机械版本</span><span>待记录</span></li><li><span>校准状态与动作范围</span><span>待核实</span></li><li><span>日志与时钟对应关系</span><span>待验证</span></li></ul><a class="button primary" href="#console">查看调试台原型</a>`}</article></section></div>`;
const caseView=()=>`<div class="wrap case-article"><section class="article-top"><div class="breadcrumb"><a href="#learn">教程</a><span>/</span><span>团队案例</span></div><header class="article-header"><span class="eyebrow">CASE NOTE / TEMPLATE</span>${badge('案例结构 · 实测待补')}<h1>一条现象，<br>怎样成为可复现的经验。</h1><p>围绕目标位置与实际回读的差异记录问题。下方是案例写作结构，当前没有团队实验结论。</p></header></section><section class="section">${[['01 / 问题现象','记录看到了什么','保留原始日志与曲线，标注发生时间和操作。避免仅写“动作不正常”。'],['02 / 适用环境','给结论划定边界','填写板卡、镜像、软件、机械、舵机版本与校准状态。当前均待团队提供。'],['03 / 判断与调整','每一步留下依据','区分现象、推测与确认结果。记录改了哪个参数，以及为何这样调整。'],['04 / 前后比较','在相同条件下测量','对齐时间、单位和条件。没有前后实测数据时，结果保持“待验证”。'],['05 / 复现与来源','让同伴可以再做一次','写清步骤、预期结果、失败现象与源码版本。补上真实照片、视频和记录链接。']].map(s=>`<div class="case-structure"><span class="eyebrow">${s[0]}</span><div><h3>${s[1]}</h3><p style="margin:16px 0 0">${s[2]}</p></div></div>`).join('')}<div class="button-row"><a href="#showcase" class="button secondary">返回实验展示</a><a href="#records" class="button primary">查看示例数据版式</a></div></section></div>`;
const connectionDetails={wifi:'<h3>电脑与板卡在同一可互通网络</h3><p>在浏览器打开板端实际地址，例如 <code>http://&lt;板端 IP&gt;:8080/</code>。地址与端口以设备配置为准。</p><ul><li>确认实际 IP、服务端口与网络隔离条件。</li><li>先核对设备与服务信息，再进入调试。</li></ul>',usb:'<h3>USB-C 1 / OTG → 虚拟网卡</h3><p>板端完成 USB gadget 配置后，使用同一网页与 API。USB-C 2 是 HOST。</p><ul><li>UDC、描述符、供电与三系统枚举需要实测。</li><li>优先核实 NCM；具体配置依主机系统与板端能力决定。</li><li>数据线接入不等同于网络已经建立。</li></ul>',ble:'<h3>官方 BLE 客户端 → 本地桥接</h3><p>优先复用 duckctl / btd。电脑薄桥接提供同源网页，能力由实际服务与带宽决定。</p><ul><li>Windows、Linux、macOS 分别验证客户端与权限。</li><li>不把浏览器直连 BLE 作为三系统主路径。</li><li>配网凭据不进入日志和导出记录。</li></ul>'};
const consoleView=()=>ConsoleWorkspace.render({state:consoleState,jointId:jointID,view:parseRoute().consolePage?.view||'joint'});
const main=document.querySelector('#main'),dialog=document.querySelector('#connection-dialog');
const jointInteractionOptions=()=>({state:consoleState,jointId:jointID,view:parseRoute().consolePage?.view,toast,redraw:redrawConsole});
function mountConsoleWorkspace(){ConsoleWorkspace.mount({state:consoleState,jointId:jointID,view:parseRoute().consolePage?.view||'joint',onSelect:id=>{jointID=id;updateSelectedJoint();}});}
function redrawConsole(){JointConsole.rememberScroll();ConsoleWorkspace.unmountView();main.innerHTML=consoleView();mountConsoleWorkspace();}
function toast(message){const el=document.querySelector('.toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),2500)}
let currentPageKey='',stopReadingNavigation=()=>{};
function parseRoute(){
  const parts=(location.hash.slice(1)||'home').split('/'),route=parts[0];
  const chapter=route==='article'&&/^chapter-\d+$/.test(parts[1]||'')?Number(parts[1].slice(8)):null;
  const consolePage=route==='console'?ConsoleWorkspace.resolve(location.hash):null;
  return {route,chapter,consolePage,key:consolePage?.key||(chapter===null?route:'article/chapter-'+chapter),anchor:consolePage?'':parts[chapter===null?1:2]||''};
}
function setReadingSection(id){document.querySelectorAll('.toc-section-link').forEach(link=>{const active=link.dataset.section===id;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')});}
function setupReadingNavigation(){const links=[...document.querySelectorAll('.toc-section-link')],sections=links.map(link=>document.getElementById(link.dataset.section)).filter(Boolean);if(!sections.length)return ()=>{};let frame=0,disposed=false,last='';const update=()=>{if(disposed)return;frame=0;const threshold=window.innerWidth<=760?48:80;let current=sections[0];for(const section of sections){if(section.getBoundingClientRect().top<=threshold)current=section;else break}const end=document.querySelector('.article-body'),atBottom=window.scrollY>0&&window.scrollY+window.innerHeight>=document.documentElement.scrollHeight-2;if(atBottom&&end&&end.getBoundingClientRect().bottom<=window.innerHeight+2)current=sections[sections.length-1];if(current.id!==last){last=current.id;setReadingSection(last);const active=document.querySelector('.toc-section-link.active'),nav=document.querySelector('.article-toc');if(active&&nav&&nav.scrollHeight>nav.clientHeight){const a=active.getBoundingClientRect(),n=nav.getBoundingClientRect();if(a.top<n.top+12)nav.scrollTop+=a.top-n.top-12;else if(a.bottom>n.bottom-12)nav.scrollTop+=a.bottom-n.bottom+12}}};const schedule=()=>{if(!disposed&&!frame)frame=requestAnimationFrame(update)};window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule);document.addEventListener('load',schedule,true);document.fonts?.ready.then(schedule);schedule();return ()=>{disposed=true;window.removeEventListener('scroll',schedule);window.removeEventListener('resize',schedule);document.removeEventListener('load',schedule,true);if(frame)cancelAnimationFrame(frame)}}
function render(){
  const {route,chapter,key,anchor,consolePage}=parseRoute(),changed=key!==currentPageKey;
  document.querySelectorAll('.site-nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+route||((route==='article'||route==='case')&&a.getAttribute('href')==='#learn')));
  if(changed){
    if(currentPageKey.startsWith('console/'))JointConsole.rememberScroll();
    if(route==='console')ConsoleWorkspace.unmountView();else ConsoleWorkspace.leave();
    stopReadingNavigation();
    main.innerHTML=route==='home'?home():route==='showcase'?showcase():route==='learn'?learn():route==='records'?records():route==='console'?consoleView():route==='case'?caseView():chapter!==null?chapterOutline(chapter):article();
    currentPageKey=key;
    if(route==='console')mountConsoleWorkspace();
  }
  document.title='Microduck Hatchery · '+(consolePage?.title||({home:'介绍',showcase:'实验展示',learn:'教程',article:'连接教程',case:'团队案例',records:'记录'}[route]||'视觉原型'));
  document.querySelector('.site-nav').classList.remove('open');
  document.querySelector('.mobile-menu').setAttribute('aria-expanded','false');
  if(anchor){
    const target=document.getElementById(anchor);
    if(target){target.scrollIntoView({block:'start'});if(route==='article')setReadingSection(anchor);}
  }else if(changed)window.scrollTo(0,0);
  if(changed&&route==='article')stopReadingNavigation=setupReadingNavigation();
}
function updateSelectedJoint(){
  const page=parseRoute().consolePage;
  if(page?.view==='single'){
    const holder=document.createElement('template');holder.innerHTML=consoleView();
    const detail=document.querySelector('.console-detail');
    if(detail)detail.replaceWith(holder.content.querySelector('.console-detail'));
  }
  JointConsole.sync(consoleState,jointID);
  document.querySelectorAll('[data-joint]').forEach(button=>{
    const selected=Number(button.dataset.joint)===jointID;
    button.setAttribute('aria-pressed',String(selected));
    button.closest('[data-joint-row],tr')?.classList.toggle('selected',selected);
  });
  ConsoleWorkspace.setContext({jointId:jointID,state:consoleState});
  if(page?.view==='single'&&window.innerWidth<=760)document.querySelector('.console-detail')?.scrollIntoView({block:'start'});
}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;if(JointConsole.handleClick(el,jointInteractionOptions()))return;if(el.matches('[data-section]')){e.preventDefault();const href=el.getAttribute('href');if(location.hash===href){document.getElementById(el.dataset.section)?.scrollIntoView({block:'start'});setReadingSection(el.dataset.section);}else location.hash=href;return}if(el.matches('.mobile-menu')){const nav=document.querySelector('.site-nav');nav.classList.toggle('open');el.setAttribute('aria-expanded',nav.classList.contains('open'));return}if(el.matches('[data-connect-open]')){document.querySelector('#connection-content').innerHTML=connectionDetails.wifi;document.querySelectorAll('[data-connect]').forEach(b=>b.setAttribute('aria-selected',b.dataset.connect==='wifi'));dialog.showModal();return}if(el.matches('[data-connect]')){document.querySelector('#connection-content').innerHTML=connectionDetails[el.dataset.connect];document.querySelectorAll('[data-connect]').forEach(b=>b.setAttribute('aria-selected',b===el));return}if(el.matches('.close-dialog,.close-on-route')){dialog.close();return}if(el.matches('[data-experiment]')){experimentIndex=Number(el.dataset.experiment);main.innerHTML=showcase();return}if(el.matches('[data-os]')){selectedOS=el.dataset.os;document.querySelectorAll('[data-os]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',b===el)});document.querySelector('#os-note').textContent=osNote();return}if(el.matches('[data-joint]')){jointID=Number(el.dataset.joint);updateSelectedJoint();return}if(el.matches('[data-record]')){recordIndex=Number(el.dataset.record);main.innerHTML=records();return}if(el.matches('[data-copy]')){const value=el.closest('.code-block').querySelector('code').textContent;try{await navigator.clipboard.writeText(value);el.textContent='已复制';setTimeout(()=>el.textContent='复制',1800)}catch{toast('请选中代码后复制。')}return}if(el.matches('[data-export]')){const csv='sample,source,relative_time_s,goal_ticks,actual_ticks\n'+sampleData.map(d=>`true,prototype-generated,${d.t.toFixed(1)},${d.goal},${d.actual.toFixed(3)}`).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='Microduck-Hatchery-EXAMPLE-ONLY.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('已下载示例 CSV；不是实测数据。')}});
document.addEventListener('change',e=>{if(JointConsole.handleChange(e.target,jointInteractionOptions()))return;if(e.target.id==='state-select'){consoleState=e.target.value;redrawConsole();document.querySelector('#state-select').focus({preventScroll:true});}});
document.addEventListener('input',e=>{if(JointConsole.handleInput(e.target,jointInteractionOptions()))return;if(e.target.id==='playback-range'){document.querySelector('#playback-time').textContent=Number(e.target.value).toFixed(1)+' s'}});
window.addEventListener('hashchange',render);render();
